import pandas as pd

def clean(df):
    df = df.copy()
    # fix label variant in sex (trailing spaces)
    if 'sex' in df.columns:
        df['sex'] = df['sex'].astype(str).str.strip()
    # parse body_mass_g which is stored as text with commas / written as text
    if 'body_mass_g' in df.columns:
        df['body_mass_g'] = df['body_mass_g'].astype(str).str.replace(',', '', regex=False).str.strip()
        df['body_mass_g'] = pd.to_numeric(df['body_mass_g'], errors='coerce')
    # fix flipper_length_mm negatives / out of range
    if 'flipper_length_mm' in df.columns:
        df['flipper_length_mm'] = pd.to_numeric(df['flipper_length_mm'], errors='coerce')
        neg_mask = df['flipper_length_mm'] < 0
        df.loc[neg_mask, 'flipper_length_mm'] = df.loc[neg_mask, 'flipper_length_mm'].abs()
    return df

def answer(df):
    dfc = clean(df)
    totals = dfc.groupby('species', dropna=False)['body_mass_g'].sum(min_count=1)
    # drop missing group keys
    result = {}
    for k, v in totals.items():
        if pd.isna(k):
            continue
        result[str(k)] = float(v) if pd.notna(v) else None
    return result
